practicalCodingChallenges.solutionCode:
function processTransactions(transactions) {
  return transactions
    .filter(t => t.status === 'completed' && t.type === 'credit')
    .map(t => t.amount * 0.02)
    .reduce((acc, reward) => acc + reward, 0);
}

