class InsufficientFundsError(Exception):
    pass

class BankAccount:
    def __init__(self, account_number: str, balance: float = 0.0):
        self.account_number = account_number
        self.balance = float(balance)

    def deposit(self, amount: float):
        if amount <= 0: raise ValueError("Deposit must be positive")
        self.balance += amount
        return self.balance

    def withdraw(self, amount: float):
        if amount > self.balance:
            raise InsufficientFundsError(f"Cannot withdraw {amount} from balance {self.balance}")
        self.balance -= amount
        return self.balance

    def __add__(self, other):
        if isinstance(other, BankAccount):
            return BankAccount(f"{self.account_number}+{other.account_number}", self.balance + other.balance)
        return NotImplemented

    def __repr__(self):
        return f"BankAccount('{self.account_number}', balance={self.balance:.2f})"

